import{_ as a,o as i,c as l,a4 as e}from"./chunks/framework.Dayh6OL6.js";const _=JSON.parse('{"title":"工程化","description":"前端工程化","frontmatter":{"title":"工程化","showArticleMetadata":true,"sort":7,"date":"2026-05-26T00:00:00.000Z","description":"前端工程化"},"headers":[],"relativePath":"knowledge/frontend/engineering.md","filePath":"pages/knowledge/frontend/engineering/README.md"}'),t={name:"knowledge/frontend/engineering.md"},n=e(`<h1 id="前端工程化学习与实战" tabindex="-1">前端工程化学习与实战 <a class="header-anchor" href="#前端工程化学习与实战" aria-label="Permalink to &quot;前端工程化学习与实战&quot;">​</a></h1><h2 id="一、核心能力目标" tabindex="-1">一、核心能力目标 <a class="header-anchor" href="#一、核心能力目标" aria-label="Permalink to &quot;一、核心能力目标&quot;">​</a></h2><ol><li>建立统一开发规范，降低协作成本。</li><li>搭建可持续交付链路（开发、测试、发布、监控）。</li><li>让项目具备长期维护能力。</li></ol><h2 id="二、工程化四层模型" tabindex="-1">二、工程化四层模型 <a class="header-anchor" href="#二、工程化四层模型" aria-label="Permalink to &quot;二、工程化四层模型&quot;">​</a></h2><ol><li>规范层：Lint、格式化、提交规范。</li><li>构建层：打包、代码分割、缓存策略。</li><li>质量层：测试、CI、代码审查。</li><li>运维层：发布、回滚、监控、告警。</li></ol><h2 id="三、基础规范建议" tabindex="-1">三、基础规范建议 <a class="header-anchor" href="#三、基础规范建议" aria-label="Permalink to &quot;三、基础规范建议&quot;">​</a></h2><h3 id="_1-代码规范" tabindex="-1">1. 代码规范 <a class="header-anchor" href="#_1-代码规范" aria-label="Permalink to &quot;1. 代码规范&quot;">​</a></h3><ul><li>ESLint：静态代码检查。</li><li>Prettier：格式统一。</li><li>Stylelint：样式规范。</li></ul><h3 id="_2-git-规范" tabindex="-1">2. Git 规范 <a class="header-anchor" href="#_2-git-规范" aria-label="Permalink to &quot;2. Git 规范&quot;">​</a></h3><ul><li>分支策略：<code>main/develop/feature/hotfix</code>。</li><li>Commit 规范：Conventional Commits。</li><li>PR 必须有变更说明与测试说明。</li></ul><h3 id="_3-目录建议" tabindex="-1">3. 目录建议 <a class="header-anchor" href="#_3-目录建议" aria-label="Permalink to &quot;3. 目录建议&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>  components/</span></span>
<span class="line"><span>  pages/</span></span>
<span class="line"><span>  hooks/</span></span>
<span class="line"><span>  services/</span></span>
<span class="line"><span>  stores/</span></span>
<span class="line"><span>  utils/</span></span>
<span class="line"><span>  styles/</span></span>
<span class="line"><span>  types/</span></span></code></pre></div><h2 id="四、构建与性能" tabindex="-1">四、构建与性能 <a class="header-anchor" href="#四、构建与性能" aria-label="Permalink to &quot;四、构建与性能&quot;">​</a></h2><ol><li>基于 Vite 或 Webpack 做按需分包。</li><li>路由懒加载、组件懒加载。</li><li>第三方库体积审查（bundle analyzer）。</li><li>资源压缩（Gzip/Brotli）。</li></ol><h2 id="五、测试体系" tabindex="-1">五、测试体系 <a class="header-anchor" href="#五、测试体系" aria-label="Permalink to &quot;五、测试体系&quot;">​</a></h2><ol><li>单元测试：Vitest/Jest。</li><li>组件测试：Testing Library。</li><li>E2E：Playwright/Cypress。</li></ol><p>建议顺序：先补关键业务路径的 E2E，再补核心工具函数单测。</p><h2 id="六、ci-cd-建议" tabindex="-1">六、CI/CD 建议 <a class="header-anchor" href="#六、ci-cd-建议" aria-label="Permalink to &quot;六、CI/CD 建议&quot;">​</a></h2><ol><li>CI 阶段：安装依赖 -&gt; lint -&gt; type-check -&gt; test -&gt; build。</li><li>CD 阶段：灰度发布 -&gt; 监控 -&gt; 全量发布。</li><li>发布策略：蓝绿发布或金丝雀发布。</li></ol><h2 id="七、监控与可观测性" tabindex="-1">七、监控与可观测性 <a class="header-anchor" href="#七、监控与可观测性" aria-label="Permalink to &quot;七、监控与可观测性&quot;">​</a></h2><ol><li>错误监控：前端异常、Promise rejection、资源加载失败。</li><li>性能监控：LCP、INP、CLS、FCP、TTFB。</li><li>日志追踪：关键用户路径埋点。</li></ol><h2 id="八、工程化落地清单" tabindex="-1">八、工程化落地清单 <a class="header-anchor" href="#八、工程化落地清单" aria-label="Permalink to &quot;八、工程化落地清单&quot;">​</a></h2><ol><li>新项目初始化脚手架模板。</li><li>接入 ESLint + Prettier + Husky + lint-staged。</li><li>接入 TypeScript 严格模式。</li><li>接入测试框架并覆盖关键链路。</li><li>接入 CI/CD 与监控报警。</li></ol><h2 id="九、常见反模式" tabindex="-1">九、常见反模式 <a class="header-anchor" href="#九、常见反模式" aria-label="Permalink to &quot;九、常见反模式&quot;">​</a></h2><ol><li>规则太多但无人执行。</li><li>发布无回滚方案。</li><li>只看构建通过，不看线上指标。</li><li>缺少文档，导致新人上手慢。</li></ol>`,25),s=[n];function o(r,h,c,d,p,u){return i(),l("div",null,s)}const m=a(t,[["render",o]]);export{_ as __pageData,m as default};
